/**
 * Engine records and enums, mirrored by hand from `core/crates/mfcore/src/model.rs`.
 *
 * The shapes follow serde's default representation, which is what the engine emits
 * through `serde_json` (the `mf` CLI) and `serde-wasm-bindgen` (the future wasm facade):
 *
 * - field names stay snake_case;
 * - enums are externally tagged: unit variants are strings (`"Canceled"`), data variants
 *   are single-key objects (`{ Segment: { segment } }`);
 * - `Option<T>` is `T | null`; `u64`/`i64` are plain numbers.
 *
 * The wasm facade task (E7) replaces this file with types generated by ts-rs into
 * `types.gen.ts`. Keep the names identical so that swap is an import change.
 */

/** A service a track can be opened in, or a site a source came from. */
export type Service =
  | 'Spotify'
  | 'AppleMusic'
  | 'YouTubeMusic'
  | 'YouTube'
  | 'Deezer'
  | 'Tidal'
  | 'AmazonMusic'
  | 'SoundCloud'
  | 'Bandcamp'
  | 'Mixcloud'
  | 'Vimeo'
  | 'TikTok'
  | 'Instagram'
  | 'Facebook'
  | 'X'
  | 'Reddit'
  | 'Twitch'
  | 'Shazam'
  | 'Genius'
  | 'Qobuz'
  | 'Pandora'
  | 'Audiomack'
  | 'Anghami'
  | 'JioSaavn'
  | 'Boomplay'
  | 'Kkbox'
  | 'YandexMusic'
  | 'NetEaseMusic'
  | 'LastFm'
  | 'Web';

export interface ServiceLink {
  service: Service;
  url: string;
  is_search: boolean;
}

export interface Track {
  title: string;
  artist: string;
  artists: string[];
  album: string | null;
  isrc: string | null;
  duration_ms: number | null;
  release_year: number | null;
  genre: string | null;
  artwork_url: string | null;
  preview_url: string | null;
  links: ServiceLink[];
  /** Provider ids: "shazam", "apple", "spotify", "deezer", "acrcloud", "audd", "youtube", "melody". */
  ids: Record<string, string>;
  identity_key: string;
}

export type SessionKind = 'Listen' | 'SystemAudio' | 'Hum' | 'Link' | 'File' | 'Lyrics';

export type SessionStatus =
  | 'Running'
  | 'Matched'
  | 'Candidates'
  | 'Completed'
  | 'NoMatch'
  | 'Failed'
  | 'Canceled'
  /** Captured while offline; identified once a connection is back (`retryWaiting`). */
  | 'Waiting';

export type SegmentKind = 'Track' | 'Unidentified' | 'Speech' | 'Silence';

export type Tier = 'Confirmed' | 'Likely' | 'Possible' | 'Unknown';

export type EvidenceSource =
  | 'Shazam'
  | 'AudD'
  | 'AcrCloud'
  | 'Metadata'
  | 'PageHint'
  | 'Melody'
  | 'Lyrics'
  | 'AcrHumming'
  | 'User';

export interface Evidence {
  source: EvidenceSource;
  at_ms: number;
  score: number;
  detail: string | null;
}

export interface Segment {
  id: string;
  item_index: number;
  start_ms: number;
  end_ms: number;
  kind: SegmentKind;
  track: Track | null;
  confidence: number;
  tier: Tier;
  evidence: Evidence[];
  alternates: Track[];
  source_url: string | null;
}

export type CandidateTier = 'Strong' | 'Possible' | 'LongShot';

export type CandidateSourceKind = 'Melody' | 'Lyrics' | 'AcrHumming' | 'Fingerprint';

export interface CandidateSource {
  kind: CandidateSourceKind;
  score: number;
  detail: string | null;
}

/** Both contours in semitones relative to the query's median; NaN (null over JSON) = unvoiced. */
export interface MelodyAlignment {
  frame_ms: number;
  query: number[];
  reference: number[];
}

export interface Candidate {
  track: Track;
  score: number;
  tier: CandidateTier;
  sources: CandidateSource[];
  alignment: MelodyAlignment | null;
}

export interface SourceInfo {
  url: string | null;
  title: string | null;
  uploader: string | null;
  thumbnail_url: string | null;
  duration_ms: number | null;
  service: Service | null;
  site: string | null;
  item_count: number;
  hints: Track[];
}

export interface PitchFrame {
  t_ms: number;
  /** Fractional MIDI note; NaN when unvoiced (JSON transports carry null). */
  midi: number | null;
  confidence: number;
}

export type Phase =
  | 'Listening'
  | 'Resolving'
  | 'Downloading'
  | 'Decoding'
  | 'Segmenting'
  | 'Recognizing'
  | 'MatchingMelody'
  | 'SearchingLyrics'
  | 'Finishing';

export type Notice =
  | 'MoveCloser'
  | 'ImpressionDetected'
  | 'KeepGoing'
  | { RateLimited: { retry_in_ms: number } }
  | 'CaptureSilent'
  | 'MelodyIndexMissing'
  | { ProviderUnavailable: { provider: string; message: string } };

export type NoMatchReason = 'TooQuiet' | 'TooShort' | 'Noisy' | 'MostlySpeech' | 'CaptureSilent' | 'NotFound';

export type Outcome =
  | { Matched: { track: Track } }
  | { Candidates: { count: number } }
  | { Completed: { identified: number; total: number } }
  | { NoMatch: { reason: NoMatchReason } }
  /** A live session could not reach the recognizer; it is stored as `Waiting`. */
  | 'Waiting';

export type ErrorCode =
  | 'InvalidInput'
  | 'UnsupportedLink'
  | 'Network'
  | 'RateLimited'
  | 'MediaUnavailable'
  | 'Decode'
  | 'Platform'
  | 'Storage'
  | 'IndexUnavailable'
  | 'Internal';

/** Events of one session, in order (docs/CORE_API.md "Events"). */
export type SessionEvent =
  | { Started: { session_id: string; kind: SessionKind } }
  | { Phase: { phase: Phase; fraction: number | null } }
  | { Progress: { analyzed_ms: number; total_ms: number; eta_ms: number | null } }
  | { Level: { rms: number; peak: number } }
  | { Pitch: { frames: PitchFrame[] } }
  | { Source: { info: SourceInfo } }
  | { Item: { index: number; count: number; title: string | null } }
  | { Segment: { segment: Segment } }
  | { SegmentRemoved: { id: string } }
  | { Candidates: { candidates: Candidate[]; is_final: boolean } }
  | { Notice: { notice: Notice } }
  | { Finished: { outcome: Outcome } }
  | { Failed: { code: ErrorCode; message: string } }
  | 'Canceled';

/**
 * `Tab` is the browser's "This tab" source (extension plan §2.1); the core gains
 * `CaptureSource::Tab` with the wasm port.
 */
export type CaptureSource = 'Microphone' | 'SystemAudio' | 'Tab';

export type ListenMode = 'Auto' | 'Recording' | 'Hum';

export interface ListenOptions {
  auto_stop: boolean;
}

export type AnalyzeMode = 'Auto' | 'Recording' | 'Impression' | 'Mix';

export interface LibraryQuery {
  kinds: SessionKind[];
  search: string | null;
  pinned_only: boolean;
  limit: number;
  offset: number;
}

export interface LibraryEntry {
  id: string;
  kind: SessionKind;
  status: SessionStatus;
  created_at_ms: number;
  title: string;
  subtitle: string | null;
  artwork_url: string | null;
  track: Track | null;
  track_count: number;
  duration_ms: number | null;
  source_url: string | null;
  pinned: boolean;
}

export interface SessionDetail {
  entry: LibraryEntry;
  source: SourceInfo | null;
  segments: Segment[];
  candidates: Candidate[];
  transcript: string | null;
}

export type ExportFormat = 'Text' | 'Csv' | 'Json' | 'Cue';

export interface MelodyIndexStatus {
  installed: boolean;
  version: string | null;
  song_count: number;
  size_bytes: number;
  available_version: string | null;
  download_bytes: number | null;
}

export interface StorageUsage {
  database_bytes: number;
  cache_bytes: number;
  melody_index_bytes: number;
}

export interface LyricLine {
  t_ms: number;
  text: string;
}

export interface Lyrics {
  plain: string;
  synced: LyricLine[];
}

/** What the page told us (extension plan §2.8 `PageContext`); filled by the page adapters. */
export interface PageContext {
  tab_id: number | null;
  url: string | null;
  title: string | null;
  /** Adapter facts (now playing, tracklist text, durations), opaque to the UI. */
  facts: Record<string, unknown> | null;
}

/** The keys of an externally tagged enum value: the variant name. */
export function variantOf<T extends string | Record<string, unknown>>(value: T): VariantName<T> {
  return (typeof value === 'string' ? value : Object.keys(value)[0]) as VariantName<T>;
}

export type VariantName<T> = T extends string ? T : keyof T & string;

/** The payload of an externally tagged variant, or undefined when `value` is another variant. */
export function payloadOf<T extends string | Record<string, unknown>, K extends VariantName<T>>(
  value: T,
  variant: K,
): VariantPayload<T, K> | undefined {
  if (typeof value === 'string') return undefined;
  return (value as Record<string, unknown>)[variant] as VariantPayload<T, K> | undefined;
}

export type VariantPayload<T, K extends string> = T extends Record<K, infer P> ? P : never;

/** The query the library views use when they want everything. */
export function libraryQuery(overrides: Partial<LibraryQuery> = {}): LibraryQuery {
  return { kinds: [], search: null, pinned_only: false, limit: 200, offset: 0, ...overrides };
}

/** A track with every optional field empty. */
export function emptyTrack(overrides: Partial<Track> = {}): Track {
  return {
    title: '',
    artist: '',
    artists: [],
    album: null,
    isrc: null,
    duration_ms: null,
    release_year: null,
    genre: null,
    artwork_url: null,
    preview_url: null,
    links: [],
    ids: {},
    identity_key: '',
    ...overrides,
  };
}
